    const bool yes = eab & ec;
    const float ncx0 = -cx0;
    const float ncx1 = -cx1;
    // (z0, z1, e) = add_ball_2_2(cy0, cy1, ncx0, ncx1)
    // (z0, z1) = add_2_2(cy0, cy1, ncx0, ncx1)
    // (z0_sh, z0_sl) = two_sum(cy0, ncx0)
