    const double yl0_l0_z = yl0_l0 - yl0_l0_h;
    const double yl0_l1 = yl0_l0_l - yl0_l0_z;
    // (yl0_h0, yl0_h1) = add_up_2_2(cy0, cy1, yl0_p0, yl0_p1)
