    const double yl0_h0 = yl0_h0_h + yl0_h0_l;
    const double yl0_h0_z = yl0_h0 - yl0_h0_h;
    const double yl0_h1 = yl0_h0_l - yl0_h0_z;
    const double yl0_al = abs_bits(yl0_l0);
